// (historia del café, Cenicafé, SCA y fuentes regionales). Las leyendas se cuentan como leyendas.
using System.Collections.Generic;

namespace FloatGardens.Historia
{
    public static class LoreData
    {
        public static readonly List<WikiEntry> All = new List<WikiEntry>
        {
            new WikiEntry { id = "hist_kaldi", category = "Historia", title = "Kaldi y las cabras: leyenda, no historia", year = "Prehistoria", place = "Bosques de montaña del suroeste de Etiopía",
                body = "El Coffea arabica nació en los bosques de montaña del suroeste de Etiopía como un híbrido natural entre Coffea canephora (el robusta) y Coffea eugenioides. Por eso tiene cuatro juegos de cromosomas (44 en total) y se autopoliniza, lo que lo hace genéticamente muy uniforme. Todavía hoy crece silvestre a la sombra de esos bosques. Según la leyenda, un pastor llamado Kaldi vio que sus cabras saltaban y no dormían después de comerse unos frutos rojos. La historia es bonita pero tardía: aparece escrita por primera vez en 1671, en un tratado en latín del erudito maronita Antoine Faustus Nairon, que ni siquiera le pone nombre al pastor. El nombre 'Kaldi' se lo agregaron después.",
                related = new[] { "hist_yemen_moca", "cul_arabica_robusta" } },
            new WikiEntry { id = "hist_yemen_moca", category = "Historia", title = "Yemen: la qahwa y el puerto de Moca", year = "Mediados del siglo XV", place = "Yemen",
                body = "La primera evidencia confiable de gente tomando café viene del Yemen, a mediados del siglo XV: los místicos sufíes lo bebían para aguantar despiertos sus rezos nocturnos. Allá el café pasó de fruto silvestre a cultivo en terrazas de montaña. La palabra viene del árabe 'qahwa', que pasó al turco como 'kahve' y al italiano como 'caffè'. Durante los siglos XVI y XVII casi todo el café del mundo salía por el puerto yemení de Moca, en el mar Rojo. De ahí viene la palabra 'moka', que hoy se usa para cafeteras italianas y para bebidas con chocolate, aunque el café original de Moca era simplemente café.",
                related = new[] { "hist_kaldi", "hist_cafes_otomanos" } },
            new WikiEntry { id = "hist_cafes_otomanos", category = "Historia", title = "Prohibiciones y cafés otomanos", year = "1511", place = "La Meca",
                body = "En 1511 el gobernador de La Meca, Khair Beg, cerró los cafés y prohibió la bebida porque allí la gente se reunía a hablar de política y a criticar al poder. La prohibición duró poco porque el sultán mameluco de El Cairo la echó para atrás. Fue la primera de muchas veces en la historia que alguien intentó prohibir el café. Según el cronista otomano Peçevi, hacia 1554 dos sirios, Hakam de Alepo y Shams de Damasco, abrieron los primeros cafés de Estambul en el barrio de Tahtakale. Los cafés otomanos se volvieron 'escuelas de sabios', donde se jugaba, se recitaba poesía y se conversaba. La cultura del café turco, preparado en cezve con molienda finísima, fue inscrita por la UNESCO como patrimonio inmaterial en 2013.",
                related = new[] { "hist_yemen_moca", "hist_europa_cafes" } },
            new WikiEntry { id = "hist_europa_cafes", category = "Historia", title = "El café conquista Europa", year = "1645", place = "Venecia, Italia",
                body = "Los comerciantes venecianos trajeron el café desde el Imperio otomano y en 1645 quedó registrado el primer café de Venecia. En 1720 abrió el Caffè Florian en la plaza de San Marcos, que todavía funciona y es uno de los cafés más antiguos de Europa. Hacia 1652 Pasqua Rosée abrió el primer café de Londres. Por un penique de entrada uno se tomaba un café y escuchaba o participaba en los debates, por eso les decían 'penny universities', universidades de un centavo. Del café de Edward Lloyd, abierto a finales del siglo XVII, nació el famoso mercado de seguros Lloyd's of London. Tras el sitio otomano de Viena en 1683 nació la leyenda de Kolschitzky, el héroe que habría encontrado los costales de café que dejó el ejército turco. Los documentos cuentan otra cosa: en enero de 1685 el comerciante armenio Johannes Diodato recibió la licencia imperial para servir café. Así arrancó la tradición de los cafés vieneses.",
                related = new[] { "hist_cafes_otomanos", "hist_declieu_martinica" } },
            new WikiEntry { id = "hist_declieu_martinica", category = "Historia", title = "Java, el rey de Francia y De Clieu", year = "1696-1714", place = "Java (Indonesia), Ámsterdam, París",
                body = "Los holandeses rompieron el monopolio yemení llevando cafetos a sus colonias: a finales del siglo XVII sembraron café en Java, y por eso en inglés 'java' se volvió sinónimo de café. En 1714 la ciudad de Ámsterdam le regaló una planta al rey Luis XIV, que terminó en el Jardín de Plantas de París. De esos cafetos viene buena parte de la línea Typica que llegó a América. El oficial naval francés Gabriel de Clieu llevó un cafeto desde París hasta la isla de Martinica. Según su propio relato, en la travesía racionaron el agua y él compartió la suya con la planta para que no se secara. De esa matica descendió buena parte de los cafetales del Caribe y de la América tropical.",
                related = new[] { "hist_palheta_brasil", "hist_europa_cafes" } },
            new WikiEntry { id = "hist_palheta_brasil", category = "Historia", title = "Palheta lleva el café a Brasil", year = "1727", place = "Guayana Francesa → Pará, Brasil",
                body = "En 1727 el oficial portugués Francisco de Melo Palheta fue de Brasil a la Guayana Francesa y volvió a Pará con semillas y plantas de café. La leyenda dice que se las dio escondidas en un ramo de flores la esposa del gobernador francés; los historiadores la ven como adorno romántico. Desde el siglo XIX Brasil es el mayor productor de café del mundo.",
                related = new[] { "hist_declieu_martinica", "hist_jesuitas_colombia" } },
            new WikiEntry { id = "hist_jesuitas_colombia", category = "Historia", title = "Cómo llegó el café a Colombia", year = "c. 1730 (libro publicado en 1741)", place = "Misión de Santa Teresa de Tabajé, confluencia de los ríos Meta y Orinoco",
                body = "El registro escrito más antiguo del café en el actual territorio colombiano se le atribuye al jesuita José Gumilla, que en 'El Orinoco ilustrado' (publicado en Madrid en 1741) cuenta que se cultivaba en la misión de Santa Teresa de Tabajé, cerca de donde el Meta cae al Orinoco. Los historiadores suelen ubicar esa siembra hacia 1730. Las semillas probablemente llegaron por Venezuela, desde las Guayanas y el Caribe.",
                related = new[] { "hist_gumilla", "hist_padre_romero" } },
            new WikiEntry { id = "hist_gumilla", category = "Historia", title = "El Orinoco ilustrado de José Gumilla", year = "c. 1730 (libro publicado en 1741)", place = "Misión de Santa Teresa de Tabajé, confluencia de los ríos Meta y Orinoco",
                body = "El registro escrito más antiguo del café en el actual territorio colombiano se le atribuye al jesuita José Gumilla, que en 'El Orinoco ilustrado' (publicado en Madrid en 1741) cuenta que se cultivaba en la misión de Santa Teresa de Tabajé, cerca de donde el Meta cae al Orinoco. Los historiadores suelen ubicar esa siembra hacia 1730. Las semillas probablemente llegaron por Venezuela, desde las Guayanas y el Caribe.",
                related = new[] { "hist_jesuitas_colombia", "hist_primeras_exportaciones" } },
            new WikiEntry { id = "hist_padre_romero", category = "Historia", title = "La penitencia del padre Romero (tradición)", year = "c. 1834", place = "Salazar de las Palmas, Norte de Santander",
                body = "Cuenta la tradición que hacia 1834 el sacerdote Francisco Romero, en Salazar de las Palmas, les ponía a sus feligreses como penitencia sembrar matas de café: entre más grave el pecado, más cafetos. Los historiadores advierten que es más tradición oral que hecho comprobado y que el café ya se sembraba en la región. Aun así, la anécdota se volvió el símbolo de cómo el grano se regó por el nororiente.",
                related = new[] { "hist_primeras_exportaciones", "hist_jesuitas_colombia" } },
            new WikiEntry { id = "hist_primeras_exportaciones", category = "Historia", title = "1835: la primera exportación salió por Cúcuta", year = "1835", place = "Aduana de Cúcuta → río Zulia → Catatumbo → lago de Maracaibo",
                body = "En 1835 quedó registrada la primera exportación formal de café colombiano: unos 2.500 sacos que salieron por la aduana de Cúcuta. Bajaron por el río Zulia y el Catatumbo hasta el lago de Maracaibo, en Venezuela, y de ahí al mar. Las fuentes no coinciden en la cifra exacta, que va de 2.560 a 2.592 sacos.",
                related = new[] { "hist_padre_romero", "hist_haciendas_viota" } },
            new WikiEntry { id = "hist_haciendas_viota", category = "Historia", title = "Las haciendas cafeteras de Cundinamarca", year = "Mediados del siglo XIX - 1906", place = "Viotá (provincia del Tequendama), Cundinamarca",
                body = "A mediados del siglo XIX el café se consolidó en grandes haciendas de Cundinamarca y Santander. Viotá, a unas dos o tres horas de Bogotá, llegó a tener hacia 1906 unas 25 haciendas que producían más de 15.000 cargas al año; el grano salía a lomo de mula hacia el río Magdalena. Muchos trabajadores pagaban la parcela que les asignaban con días de trabajo para la hacienda.",
                related = new[] { "hist_primeras_exportaciones", "hist_colonizacion_antioquena" } },
            new WikiEntry { id = "hist_fnc_1927", category = "Historia", title = "1927: nace la Federación Nacional de Cafeteros", year = "1927", place = "Medellín",
                body = "El 27 de junio de 1927, durante el Segundo Congreso Nacional de Cafeteros en Medellín, los productores fundaron la Federación Nacional de Cafeteros de Colombia. La idea era que los mismos caficultores se organizaran para defender el precio, mejorar la calidad y promocionar el café colombiano en el mundo.",
                related = new[] { "hist_cenicafe_1938", "hist_juan_valdez_1958" } },
            new WikiEntry { id = "hist_cenicafe_1938", category = "Historia", title = "Cenicafé, el laboratorio del café", year = "1938", place = "Chinchiná, Caldas (Planalto, vía a Manizales)",
                body = "En 1938 la Federación creó Cenicafé, el Centro Nacional de Investigaciones de Café, con sede en Chinchiná (Caldas). Allá se han desarrollado variedades resistentes a la roya, sistemas de beneficio ecológico que ahorran agua y buena parte de la ciencia cafetera de Colombia.",
                related = new[] { "hist_variedad_colombia_1982", "hist_fnc_1927" } },
            new WikiEntry { id = "hist_juan_valdez_1958", category = "Historia", title = "La campaña que le puso cara al café colombiano", year = "1958-1959", place = "Estados Unidos / Colombia",
                body = "Para que en Estados Unidos supieran que el café colombiano era distinto del resto, la Federación le encargó una campaña a la agencia Doyle Dane Bernbach. Entre 1958 y 1959 nació así el personaje publicitario Juan Valdez, un caficultor con su mula Conchita, que se volvió símbolo del país. En diciembre de 2002 abrió en el aeropuerto El Dorado de Bogotá la primera tienda de la marca.",
                related = new[] { "hist_fnc_1927", "hist_dop_cafe_colombia" } },
            new WikiEntry { id = "hist_variedad_colombia_1982", category = "Historia", title = "La Variedad Colombia llegó antes que la roya", year = "1982", place = "Cenicafé, Chinchiná",
                body = "Cenicafé se adelantó a la enfermedad: a finales de 1982 entregó la Variedad Colombia, de porte bajo, que resultó de cruzar Caturra con el Híbrido de Timor. Ese híbrido es un cruce natural entre arábica y robusta que aporta los genes de resistencia a la roya. El Híbrido de Timor es un cruce natural entre arábica y robusta encontrado en la isla de Timor, que le aportó al arábica genes de resistencia a la roya. Cenicafé, el centro de investigación cafetera fundado en 1938 en Chinchiná (Caldas), cruzó Caturra con Híbrido de Timor y en 1982 entregó la variedad Colombia, la primera resistente a la roya del país, ¡antes de que la enfermedad llegara! Es una variedad compuesta, mezcla de varias líneas, para que la resistencia dure más.",
                related = new[] { "hist_roya_llega", "hist_cenicafe_1938" } },
            new WikiEntry { id = "hist_roya_llega", category = "Historia", title = "1983: la roya aparece en Colombia", year = "1983", place = "Chinchiná, Caldas",
                body = "La roya del cafeto, causada por el hongo Hemileia vastatrix, se detectó en Colombia en septiembre de 1983, en Chinchiná (Caldas), trece años después de llegar a Brasil en 1970. El hongo forma manchas de polvillo anaranjado en el envés de las hojas, que se caen y dejan el árbol débil.",
                related = new[] { "hist_variedad_colombia_1982", "hist_epidemia_roya_castillo" } },
            new WikiEntry { id = "hist_epidemia_roya_castillo", category = "Historia", title = "La gran epidemia de roya y la renovación con Castillo", year = "2008-2012", place = "Zona cafetera colombiana",
                body = "Entre 2008 y 2011 las lluvias excesivas, sobre todo con La Niña, y unos cafetales viejos y susceptibles dispararon una epidemia de roya. La producción cayó de unos 11,5 millones de sacos en 2008 a cerca de 7,8 millones en 2009, y en 2012 tocó fondo con 7,7 millones, la cosecha más baja en más de tres décadas. La respuesta fue una renovación masiva de cafetales con variedades resistentes, sobre todo Castillo, que Cenicafé liberó en 2005 y adaptó por regiones. El esfuerzo dio frutos: en 2015 Colombia cosechó unos 14,2 millones de sacos, la mejor cosecha en 23 años.",
                related = new[] { "hist_roya_llega", "cul_roya" } },
            new WikiEntry { id = "hist_dop_cafe_colombia", category = "Historia", title = "Café de Colombia, origen protegido", year = "2005-2007", place = "Colombia / Unión Europea",
                body = "En 2005 la Superintendencia de Industria y Comercio reconoció 'Café de Colombia' como denominación de origen, y en septiembre de 2007 la Unión Europea lo registró como Indicación Geográfica Protegida, el primer producto no europeo con esa protección. Después llegaron denominaciones regionales como Café de Nariño, del Cauca, del Huila y de Santander. 'Café de Colombia' fue protegido como denominación de origen en Colombia en 2005. Después llegaron las denominaciones regionales: Nariño y Cauca (2011), Huila (2013), Santander (2014), y Tolima y Sierra Nevada (2017). Cada una reconoce que el clima, el suelo y la gente de esa zona le dan a la taza un carácter propio.",
                related = new[] { "hist_paisaje_cultural_unesco", "hist_juan_valdez_1958" } },
            new WikiEntry { id = "hist_paisaje_cultural_unesco", category = "Historia", title = "Paisaje Cultural Cafetero, patrimonio mundial", year = "2011", place = "Caldas, Quindío, Risaralda y norte del Valle del Cauca",
                body = "El 25 de junio de 2011 la UNESCO inscribió el Paisaje Cultural Cafetero de Colombia en la lista de Patrimonio Mundial. El área principal cubre 47 municipios y 411 veredas, más una zona de amortiguamiento, con sus casas de bahareque, guaduales y cafetales en ladera.",
                related = new[] { "col_jeep_willys", "col_palma_cera" } },
            new WikiEntry { id = "hist_olas_especialidad", category = "Historia", title = "El café de especialidad y sus tres olas", year = "1974-1982", place = "Estados Unidos",
                body = "La expresión 'specialty coffee' la popularizó la importadora Erna Knutsen en la revista Tea & Coffee Trade Journal, en 1974, para hablar de cafés de microclimas especiales con sabores únicos. En 1982 se fundó la Specialty Coffee Association of America. Hoy un café se considera de especialidad si saca 80 puntos o más sobre 100 en catación. Se habla de 'olas' del café: la primera, del café enlatado y de consumo masivo; la segunda, de las cadenas de cafeterías con espresso y bebidas con leche, como Peet's (1966) y Starbucks (1971); y la tercera, del café como producto artesanal con finca, variedad y proceso visibles. El término 'tercera ola' se le atribuye a la tostadora Trish Rothgeb, en un artículo de comienzos de los años 2000.",
                related = new[] { "cat_puntaje_especialidad", "hist_aeropress_2005" } },
            new WikiEntry { id = "hist_aeropress_2005", category = "Historia", title = "La AeroPress: un ingeniero, un garaje y 2005", year = "2005", place = "California, Estados Unidos",
                body = "La AeroPress la inventó Alan Adler, ingeniero y profesor de Stanford, famoso por el Aerobie, un aro volador con el que se impuso un récord Guinness de lanzamiento. Adler quería una taza individual menos amarga y menos ácida: empezó a hacer prototipos en su garaje en 2004 y presentó la AeroPress en noviembre de 2005 en una feria de la industria del café. En 2017 su empresa, Aerobie, vendió la marca de juguetes y pasó a llamarse AeroPress, Inc. La AeroPress la inventó el ingeniero estadounidense Alan Adler, el mismo del disco volador Aerobie, y salió al mercado en noviembre de 2005 tras más de 30 prototipos. Funciona como una jeringa: el café se infusiona y luego se presiona a través de un filtro de papel. En 2008 se hizo en Oslo el primer Campeonato Mundial de AeroPress, con solo tres competidores; hoy compiten baristas de decenas de países.",
                related = new[] { "pre_aeropress_metodos", "comp_wac" } },
            new WikiEntry { id = "hist_espresso", category = "Historia", title = "De la máquina de vapor al espresso con crema", year = "1884-1947", place = "Turín y Milán, Italia",
                body = "En 1884 Angelo Moriondo, de Turín, patentó una máquina de café a vapor; en 1901 Luigi Bezzera, de Milán, patentó mejoras como el portafiltro, y Desiderio Pavoni compró la patente para fabricar máquinas comerciales. En 1938 Achille Gaggia patentó un sistema sin vapor y en 1947 su máquina de palanca, que empujaba el agua a alta presión y creó la famosa 'crema'. Hoy un espresso se extrae a unos 9 bares en 25 a 30 segundos.",
                related = new[] { "pre_espresso", "hist_olas_especialidad" } },
            new WikiEntry { id = "bog_tinto", category = "Bogotá", title = "Un tintico", year = "", place = "Colombia, en especial Bogotá",
                body = "En Colombia un 'tinto' es una taza pequeña de café negro, muchas veces con azúcar o panela, que se vende hasta en la calle en termos. La palabra viene del latín 'tinctus' (teñido), que se usaba para líquidos oscuros como el vino. Durante décadas el mejor grano se exportaba y en el país se tomaba sobre todo café de menor calidad, la 'pasilla'.",
                related = new[] { "pre_bebidas_colombianas", "bog_cafes_historicos" } },
            new WikiEntry { id = "bog_altitud_ebullicion", category = "Bogotá", title = "En Bogotá el agua hierve a unos 91 °C", year = "", place = "Bogotá",
                body = "A unos 2.600 metros la presión del aire es más o menos tres cuartas partes de la que hay a nivel del mar, así que el agua hierve hacia los 91-92 °C y no a 100 °C. Por más que la tetera pite, en una cocina bogotana con olla abierta nunca vas a tener agua a 96 °C. O sea que el agua 'recién hervida' ya llega rozando el borde bajo del rango que la SCA recomienda para filtrados.",
                related = new[] { "pre_temperatura", "bog_2600" } },
            new WikiEntry { id = "bog_cafes_historicos", category = "Bogotá", title = "Los cafés de tertulia del centro", year = "1912-mediados del siglo XX", place = "Centro de Bogotá y La Candelaria (Café Windsor, El Automático, Café Pasaje)",
                body = "En la primera mitad del siglo XX el centro de Bogotá vivía de las tertulias: en el Café Windsor, abierto hacia 1912, se reunían escritores de la generación de Los Nuevos como León de Greiff y Germán Arciniegas, y en El Automático la tertulia giraba alrededor de De Greiff. De los cerca de 70 cafés de tertulia de mediados de siglo quedan muy pocos. Uno de los sobrevivientes es el Café Pasaje, fundado en 1936 y hoy frente a la plazoleta del Rosario.",
                related = new[] { "bog_tinto", "hist_europa_cafes" } },
            new WikiEntry { id = "bog_2600", category = "Bogotá", title = "2.600 metros más cerca de las estrellas", year = "", place = "Bogotá",
                body = "Bogotá queda a unos 2.600 metros sobre el nivel del mar, con una temperatura media de unos 14 °C: demasiado frío para el café, que en Colombia se da sobre todo entre 1.200 y 2.000 metros. De su altura sale el lema '2.600 metros más cerca de las estrellas', que hace parte de la marca de la ciudad. Por eso cultivar café en Bogotá solo es posible bajo techo, como en Float Gardens. Bogotá está a unos 2.600 m de altura, con una temperatura media cercana a 14 °C, y en las temporadas secas caen heladas en la Sabana. El café arábica prospera más o menos entre 18 y 22 °C de temperatura media, así que en la capital no se da al aire libre. De ahí nace la idea de Float Gardens: cultivar cafetos dentro de casas y bodegas, con luz y temperatura controladas.",
                related = new[] { "bog_altitud_ebullicion", "cul_hidroponia" } },
            new WikiEntry { id = "col_cordilleras", category = "Colombia", title = "Las tres cordilleras", year = "", place = "Nudo de los Pastos y Macizo Colombiano",
                body = "Los Andes entran a Colombia por Nariño y se abren en tres ramales: en el Nudo de los Pastos se separa la cordillera Occidental, y en el Macizo Colombiano (entre Cauca y Huila) se dividen la Central y la Oriental. En el Macizo nacen los ríos Magdalena y Cauca. El café colombiano crece en las laderas de las tres cordilleras, por eso el mapa cafetero son franjas largas que siguen las montañas de sur a norte. En el colegio, los colombianos aprenden los pisos térmicos: cálido (hasta unos 1.000 m), templado (entre 1.000 y 2.000 m), frío (entre 2.000 y 3.000 m) y páramo (por encima de los 3.000 m). El café es un cultivo de clima templado. Bogotá, a unos 2.600 m, está en piso frío, y por eso el protagonista tiene que cultivar bajo techo.",
                related = new[] { "col_cinturon_cafetero", "cul_altitud_densidad" } },
            new WikiEntry { id = "col_cinturon_cafetero", category = "Colombia", title = "El cinturón del café", year = "", place = "Colombia, de Nariño a la Sierra Nevada",
                body = "El café se cultiva en el llamado cinturón cafetero, la franja del planeta entre los trópicos de Cáncer y Capricornio. La zona cafetera colombiana va desde Nariño, cerca de 1° de latitud norte, hasta la Sierra Nevada, a unos 11° norte. Tan cerca del ecuador los días duran casi lo mismo todo el año, y lo que hace las veces de estaciones es la altura: subir la montaña es como viajar a un clima más fresco.",
                related = new[] { "col_cordilleras", "cul_clima_ideal" } },
            new WikiEntry { id = "col_cosecha_mitaca", category = "Colombia", title = "Cosecha principal y mitaca", year = "", place = "Zona cafetera central de Colombia",
                body = "En buena parte de la zona cafetera hay dos temporadas de lluvias al año, más o menos de marzo a mayo y de septiembre a noviembre, porque la Zona de Convergencia Intertropical, el cinturón de nubes del ecuador, pasa dos veces sobre el país. Cada temporada seca seguida de aguaceros dispara una floración, y por eso hay dos cosechas: la principal, la más grande, y la mitaca o traviesa, más pequeña. En la zona cafetera central de Colombia hay dos temporadas de lluvia y dos secas al año, así que hay dos floraciones y dos cosechas: la principal y la mitaca, también llamada traviesa. En las zonas norte, oriente y sur predomina una sola temporada de lluvias y se concentra una cosecha principal al año. Por esa diversidad, en algún rincón de Colombia casi siempre se está recogiendo café.",
                related = new[] { "col_cinturon_cafetero", "cul_floracion" } },
            new WikiEntry { id = "col_sombrio", category = "Colombia", title = "El sombrío: guamo y plátano", year = "", place = "Zona cafetera colombiana",
                body = "En muchas fincas el café crece bajo árboles de sombra. El guamo es una leguminosa que aporta nitrógeno y hojarasca al suelo; el plátano da sombra temporal mientras crecen los árboles y además comida para la familia. También se usan el nogal cafetero y el carbonero. La sombra regula la temperatura y la humedad, protege el suelo de la erosión y es refugio de aves, incluidas aves migratorias.",
                related = new[] { "col_cordilleras", "cul_clima_ideal" } },
            new WikiEntry { id = "col_jeep_willys", category = "Colombia", title = "El Willys y el Desfile del Yipao", year = "1946", place = "Eje Cafetero (Quindío, Caldas, Risaralda)",
                body = "Los Jeep Willys llegaron a Colombia hacia 1946 y pronto los cafeteros los adoptaron como 'mulitas mecánicas' para subir y bajar por las trochas. 'Yipao' es la carga completa que cabe en un Willys: bultos de café, racimos de plátano, muebles y hasta gente. En el Quindío la palabra se volvió casi una unidad de medida. En Armenia, durante las fiestas de aniversario de la ciudad en octubre, se celebra el Desfile del Yipao desde finales de los años ochenta. Desfilan Willys cargados de café, plátano o trasteos enteros, y algunos conductores levantan las llantas delanteras y avanzan sobre las traseras. Es una fiesta a la cultura cafetera y al trabajo de llevar la cosecha montaña abajo.",
                related = new[] { "hist_paisaje_cultural_unesco", "col_arrieros" } },
            new WikiEntry { id = "col_palma_cera", category = "Colombia", title = "La palma de cera, árbol nacional", year = "1985", place = "Valle de Cocora, Salento, Quindío",
                body = "La palma de cera del Quindío (Ceroxylon quindiuense) es el árbol nacional de Colombia desde la Ley 61 de 1985, que prohíbe talarla. Puede llegar a unos 60 m, lo que la hace una de las palmas más altas del mundo, y tarda décadas en madurar. El Valle de Cocora, en Salento, está entre unos 1.800 y 2.400 m, por encima de la franja cafetera, y es famoso por sus palmas entre la neblina.",
                related = new[] { "hist_paisaje_cultural_unesco", "col_jeep_willys" } },
            new WikiEntry { id = "col_recolectores", category = "Colombia", title = "Chapoleras y recolectores", year = "", place = "Eje Cafetero",
                body = "A las mujeres recolectoras de café se les llama chapoleras, y durante décadas trabajaron hombro a hombro con los recolectores. Su traje tradicional, con falda amplia, pañoleta y delantal, se volvió símbolo de la cultura cafetera en desfiles y fiestas. 'Chapola' quiere decir mariposa en el habla colombiana, aunque el origen exacto del nombre se discute. Por las pendientes tan fuertes y porque en una misma rama hay frutos verdes, pintones y maduros, en Colombia el café se recoge a mano, grano por grano, pasando varias veces por el mismo lote. El recolector lleva un coco o canasto amarrado a la cintura. Solo se debe coger la cereza madura: unos pocos granos verdes en la mezcla bastan para dañar la taza.",
                related = new[] { "ben_recoleccion_selectiva", "cul_rere" } },
            new WikiEntry { id = "col_indigenas_sierra", category = "Colombia", title = "El café del 'corazón del mundo'", year = "1995", place = "Sierra Nevada de Santa Marta",
                body = "En la Sierra Nevada de Santa Marta, la montaña costera más alta del mundo, viven los pueblos arhuaco, kogui, wiwa y kankuamo, que la consideran el 'corazón del mundo'. Muchas familias indígenas cultivan café orgánico bajo sombra y se han organizado en asociaciones que exportan directamente; una de las más conocidas tiene sede en Pueblo Bello (Cesar) y nació en 1995.",
                related = new[] { "col_cinturon_cafetero", "col_resguardos_sur" } },
            new WikiEntry { id = "cul_arabica_robusta", category = "Cultivo", title = "Arábica y robusta: las dos grandes", year = "", place = "Mundo / Colombia",
                body = "Casi todo el café del mundo sale de dos especies: Coffea arabica y Coffea canephora, a la que le dicen robusta. El arábica prefiere tierras altas y frescas y da tazas más dulces, ácidas y aromáticas; el robusta aguanta más calor y enfermedades y tiene casi el doble de cafeína (alrededor de 2,2-2,7 % frente a 1,2-1,5 % del arábica). Colombia es reconocida en el mundo por cultivar café arábica. El arábica nació en las montañas del suroccidente de Etiopía como un cruce natural entre dos especies emparentadas con Coffea canephora y Coffea eugenioides; por eso tiene 44 cromosomas, el doble que los demás cafés. Es la única especie de Coffea autofértil: la flor se poliniza con su propio polen. El robusta y casi todas las otras especies, en cambio, necesitan polen de una planta genéticamente distinta.",
                related = new[] { "hist_kaldi", "cul_variedades" } },
            new WikiEntry { id = "cul_ciclo_vida", category = "Cultivo", title = "De la semilla a la primera cosecha", year = "", place = "Colombia",
                body = "La mata de café arranca en un germinador: un cajón elevado mínimo 40 cm del suelo, lleno de arena de río fina y lavada, donde se siembra la semilla todavía con su pergamino. Elevarlo evita salpicaduras y el hongo Rhizoctonia solani, que tumba las plántulas. La semilla de café pierde viabilidad con el tiempo, por eso se usa semilla fresca y certificada; el proceso hasta la chapola toma cerca de dos meses. Las chapolas se trasplantan a bolsas con tierra y materia orgánica, el almácigo, donde se quedan entre 4 y 6 meses según el tamaño de la bolsa, la fertilidad del sustrato y el clima. Ahí desarrollan raíz y varios pares de hojas verdaderas antes de ir al campo. Una chapola mal sembrada, con la raíz doblada o torcida, se vuelve una mata débil por años. Después del trasplante al campo, la mata de arábica tarda alrededor de año y medio a dos años en dar su primera cosecha comercial. Sumando germinador y almácigo, desde la semilla hasta la primera taza pasan cerca de dos años y medio a tres. Por eso sembrar café es una apuesta a largo plazo.",
                related = new[] { "cul_fosforito_chapola", "cul_floracion" } },
            new WikiEntry { id = "cul_fosforito_chapola", category = "Cultivo", title = "Del fosforito a la chapola", year = "", place = "Zona cafetera colombiana",
                body = "Unas semanas después de sembrada, la semilla saca un tallito con el grano todavía pegado arriba, como un fósforo: es la etapa de 'fosforito'. Cuando cae esa cubierta y se abren las dos hojas cotiledonares, redondeadas como alas, la plántula se llama 'chapola', como les dicen a las mariposas en la zona cafetera. Cenicafé recomienda pasar al almácigo en estado de chapola y no de fósforo, porque en esa etapa la plántula es más vulnerable a Rhizoctonia.",
                related = new[] { "cul_ciclo_vida", "cul_hidroponia" } },
            new WikiEntry { id = "cul_floracion", category = "Cultivo", title = "La lluvia despierta las flores", year = "", place = "Zona cafetera colombiana",
                body = "Los botones florales del café se quedan 'dormidos' hasta que llega un periodo seco seguido de lluvia. Según observaciones de Cenicafé, las flores se abren unos 10 días después de un aguacero de 10 mm o más, si antes hubo una semana o más de poca lluvia. Las flores son blancas, huelen parecido al jazmín y duran abiertas apenas unos días. Desde la floración hasta la cereza madura, el arábica tarda unas 30 a 34 semanas, es decir 7 a 8 meses; el robusta es más lento, entre 9 y 11 meses. En estudios de Cenicafé con variedad Colombia, la mejor taza salió de frutos cosechados entre 210 y 224 días después de la floración, y la madurez completa llegó hacia los 240 días. El fruto crece despacio los primeros dos meses, luego se 'infla' rápido y al final se llena y cambia de color.",
                related = new[] { "cul_maduracion_colores", "col_cosecha_mitaca" } },
            new WikiEntry { id = "cul_anatomia_cereza", category = "Cultivo", title = "Por dentro de una cereza de café", year = "", place = "",
                body = "La cereza de café tiene capas como una cebolla: afuera la cáscara o exocarpio, luego la pulpa y el mucílago azucarado (mesocarpio), después el pergamino (endocarpio), una piel delgadita llamada película plateada y, en el centro, la almendra con el embrión. Normalmente trae dos semillas enfrentadas por su cara plana. En el beneficio se quitan la pulpa y el mucílago, y en la trilla se quita el pergamino para obtener el café verde o almendra. A veces solo una de las dos semillas de la cereza se desarrolla y la almendra crece redonda y ovalada: en Colombia le dicen 'caracol' y en inglés 'peaberry'. Aparece en una fracción pequeña de los granos y se separa por tamaño y forma con zarandas en la trilla. Algunos tostadores lo venden aparte como un lote especial.",
                related = new[] { "ben_despulpado", "cul_maduracion_colores" } },
            new WikiEntry { id = "cul_maduracion_colores", category = "Cultivo", title = "Verde, pintón, maduro, sobremaduro y seco", year = "", place = "Colombia",
                body = "En la misma rama conviven frutos verdes, pintones (empezando a cambiar de color), maduros (rojo o amarillo intenso según la variedad), sobremaduros (oscuros, color vino) y secos (negros y arrugados). Cenicafé encontró la mejor taza en frutos pintones, maduros y sobremaduros cosechados a tiempo. Los verdes dan sabores astringentes y pesan menos, y los secos que quedan en el árbol o en el suelo se vuelven refugio de la broca.",
                related = new[] { "ben_recoleccion_selectiva", "cul_rere" } },
            new WikiEntry { id = "cul_variedades", category = "Cultivo", title = "Variedades: Típica, Borbón y Caturra", year = "Siglo XVIII", place = "Colombia",
                body = "La Típica fue la variedad que predominó en Colombia durante buena parte de su historia cafetera. Es de porte alto, con hojas nuevas color bronce y fruto rojo; produce poco pero puede dar una taza limpia y elegante. Fue desplazada por variedades más productivas como el Caturra y, después de la llegada de la roya, por variedades resistentes, porque es susceptible a esa enfermedad. El Borbón viene de la isla de Bourbon, hoy La Reunión, en el océano Índico, adonde los franceses llevaron café desde Yemen a comienzos del siglo XVIII. Produce más que la Típica, sus hojas nuevas son verdes y hay Borbón de fruto rojo y de fruto amarillo. Es apreciado por su dulzura, pero también es susceptible a la roya. El Caturra es una mutación natural enana del Borbón encontrada en Minas Gerais, Brasil, entre 1915 y 1918. Sus entrenudos cortos permiten sembrar muchas más matas por hectárea, y desde los años setenta se expandió por Colombia en cafetales tecnificados a libre exposición solar. Da buena taza y buena producción, pero es susceptible a la roya.",
                related = new[] { "cul_variedades_resistentes", "cul_variedades_exoticas" } },
            new WikiEntry { id = "cul_roya", category = "Cultivo", title = "La roya: el polvillo naranja", year = "1869 / 1983", place = "Sri Lanka / Chinchiná, Caldas",
                body = "La roya del cafeto la causa el hongo Hemileia vastatrix, que forma un polvillo naranja en el envés de las hojas y las tumba, debilitando la mata. Sus esporas viajan con el viento y la lluvia y necesitan agua líquida sobre la hoja para germinar. En Ceilán (hoy Sri Lanka) una epidemia que empezó en 1869 arruinó los cafetales y la isla se pasó al té; en Colombia se confirmó el 27 de septiembre de 1983 en Chinchiná, Caldas.",
                related = new[] { "hist_epidemia_roya_castillo", "cul_variedades_resistentes" } },
            new WikiEntry { id = "cul_broca", category = "Cultivo", title = "La broca: un cucarrón diminuto", year = "1988", place = "Nariño",
                body = "La broca del café (Hypothenemus hampei) es un cucarroncito de menos de 2 mm, originario de África central, que se detectó en Colombia en 1988 en el sur de Nariño. La hembra perfora la cereza por el 'ombligo', pone 2 o 3 huevos por día durante unas tres semanas y sus larvas se comen la almendra. A unos 25 °C completa su ciclo de huevo a adulto en menos de un mes; hay cerca de diez hembras por cada macho, y los machos, que no vuelan, se aparean con sus hermanas dentro del mismo fruto.",
                related = new[] { "cul_rere", "ben_defectos" } },
            new WikiEntry { id = "cul_rere", category = "Cultivo", title = "Re-Re y control biológico de la broca", year = "", place = "Colombia",
                body = "La práctica más importante contra la broca es el Re-Re: recolectar a tiempo todos los frutos maduros y hacer repases para no dejar frutos maduros, sobremaduros o secos en el árbol ni en el suelo. Cenicafé encontró que las brocas que atacan la nueva cosecha salen precisamente de esos frutos olvidados. La meta del manejo integrado es mantener la infestación por debajo del 2 %; sin control puede pasar del 15 % y llegar hasta un 33 %. El hongo Beauveria bassiana infecta a la broca y la cubre con un moho blanco; Cenicafé recomienda la cepa Bb9205, aplicada dirigida a los frutos infestados. También se trajeron de África avispitas parasitoides como Cephalonomia stephanoderis, Prorops nasuta y Phymastichus coffea, y se usan trampas con atrayentes a base de alcoholes para monitorear y capturar brocas en vuelo. La idea es combinar todo y dejar los insecticidas como último recurso.",
                related = new[] { "cul_broca", "ben_recoleccion_selectiva" } },
            new WikiEntry { id = "cul_hidroponia", category = "Cultivo", title = "Balsas flotantes: café sin tierra", year = "", place = "Bogotá (bodega de Float Gardens)",
                body = "En la hidroponía de balsa flotante (aguas profundas o DWC), las plántulas van en una lámina de icopor que flota sobre una solución nutritiva y las raíces cuelgan en el agua. Como las raíces del café necesitan oxígeno, hay que airear con bombas y difusores; como guía, más de 6 mg/L de oxígeno disuelto y el agua entre 18 y 22 °C, porque el agua tibia favorece hongos de raíz como Pythium. Hay pocos estudios de café en hidroponía, así que Float Gardens experimenta: la balsa funciona bien para chapolas y almácigo, y las matas adultas pueden pasar a contenedores con sustrato y fertirriego. La conductividad eléctrica (CE) mide cuántas sales nutritivas tiene la solución. Como punto de partida para café bajo techo se usa una CE baja, alrededor de 1,0 mS/cm para plántulas y hasta cerca de 2,0 mS/cm para plantas grandes; un estudio en Brasil con plántulas de arábica encontró que la solución menos concentrada (CE 1,0) fue la más eficiente. El pH de la solución se mantiene alrededor de 5,5 a 6,2 para que los nutrientes estén disponibles.",
                related = new[] { "cul_clima_ideal", "bog_2600" } },
            new WikiEntry { id = "cul_clima_ideal", category = "Cultivo", title = "El clima que le gusta al cafeto (y la bodega)", year = "", place = "Zona cafetera colombiana",
                body = "Cenicafé señala que el cafeto se desarrolla bien entre 1.000 y 2.000 metros de altura, con temperatura media de 19 a 21,5 °C, entre 1.800 y 2.000 mm de lluvia al año (unos 120 mm por mes) y de 1.500 a 1.800 horas de sol al año. La fotosíntesis de la hoja funciona mejor alrededor de 24 °C. A mayor altura el grano madura más despacio, algo que suele asociarse con más acidez y complejidad en la taza. En el trópico el día dura cerca de 12 horas todo el año, así que en la bodega se programan las lámparas LED con 12 horas de luz y 12 de oscuridad. El café se adapta a la sombra, pero sus hojas aprovechan bien luz más intensa; como guía práctica se usan unos 300 a 500 µmol/m²/s de luz útil (PPFD), 20 a 24 °C de día, 16 a 18 °C de noche y humedad relativa de 60 a 80 %. Hay que evitar que las hojas queden mojadas por horas, porque eso es justo lo que necesitan las esporas de roya para germinar.",
                related = new[] { "cul_hidroponia", "cul_altitud_densidad" } },
            new WikiEntry { id = "cul_altitud_densidad", category = "Cultivo", title = "Más arriba, más lento: la altura en la taza", year = "", place = "Zona cafetera colombiana",
                body = "Por cada 100 m que se sube, la temperatura baja más o menos 0,6 °C. Con más altura y frío, la cereza madura más despacio, y el grano tiende a ser más denso y de acidez más brillante. Por eso la altura se asocia con calidad, aunque estudios de Cenicafé muestran que el suelo, la variedad y el beneficio pesan igual o más. La mayoría de cafetales colombianos está más o menos entre 1.200 y 1.800 m.",
                related = new[] { "col_cordilleras", "cul_clima_ideal" } },
            new WikiEntry { id = "ben_recoleccion_selectiva", category = "Beneficio", title = "Grano a grano: la recolección selectiva", year = "", place = "Zona cafetera colombiana",
                body = "En las laderas colombianas el café se recoge a mano, cereza por cereza, porque en una misma rama conviven frutos verdes, pintones y maduros. Según Cenicafé, una buena recolección tiene más del 80 % de frutos maduros y menos del 2,5 % de verdes; si se pasa de ese límite aparecen granos vinagre, inmaduros y negros. Para controlarlo, Cenicafé creó el Mediverdes, una herramienta para medir cuántos verdes trae lo recolectado. Antes de despulpar, muchas fincas echan la cereza en un tanque o tolva con agua: los frutos sanos y densos se hunden, mientras los vanos, secos o brocados flotan. Esos 'flotes' se separan porque dañarían la taza. Es una de las clasificaciones más sencillas y baratas de todo el beneficio.",
                related = new[] { "col_recolectores", "cul_maduracion_colores" } },
            new WikiEntry { id = "ben_despulpado", category = "Beneficio", title = "Despulpado: quitarle el vestido a la cereza", year = "2003", place = "",
                body = "El despulpado retira la piel y la pulpa con una máquina despulpadora, idealmente el mismo día de la recolección. Según Cenicafé, la pulpa es cerca del 43,6 % del peso del fruto fresco (unos 436 g por kilo de cereza) y tiene entre 76 % y 80 % de humedad. Cenicafé recomienda despulpar sin agua, y una despulpadora mal calibrada muerde o corta granos que luego aparecen como defecto. La cereza recién cogida es casi todo agua, pulpa y mucílago. Un estudio de Cenicafé con variedad Colombia encontró que se necesitan unos 5,04 kg de cereza madura (y 5,25 kg de sobremadura) para obtener 1 kg de café pergamino seco. Coger fruto en su punto no es solo cuestión de sabor: también rinde más.",
                related = new[] { "ben_fermentacion", "ben_pulpa" } },
            new WikiEntry { id = "ben_fermentacion", category = "Beneficio", title = "Mucílago y fermentación", year = "", place = "",
                body = "Debajo de la pulpa queda el mucílago, una capa babosa y dulce rica en pectinas y azúcares, que en la variedad Colombia equivale a cerca del 14,85 % del peso del fruto fresco. En el café lavado hay que retirarlo antes de secar, ya sea fermentándolo en tanques o con desmucilaginadoras mecánicas como las de la tecnología Becolsub de Cenicafé. Cuánto mucílago se quita o se deja es lo que distingue un lavado, un honey y un natural. En el lavado tradicional colombiano el café despulpado reposa en tanques mientras levaduras y bacterias degradan el mucílago; según Cenicafé esto toma entre 12 y 18 horas, dependiendo de la temperatura, y el pH baja de cerca de 5,0 a 3,3. Pero el reloj no manda: con el Fermaestro se revisa desde la hora 10 y luego cada una o dos horas, y cuando la masa llega a la marca, se lava. Pasarse más de 2 horas del punto trae defectos como vinagre, fermento, cebolla o rancio. En la finca también se usan pruebas de toda la vida: el palo que deja el hueco en la masa o el grano que, frotado, se siente áspero y suena a 'cascajo'.",
                related = new[] { "ben_lavado", "ben_anaerobico" } },
            new WikiEntry { id = "ben_lavado", category = "Beneficio", title = "Suaves lavados: el sello de Colombia", year = "", place = "Colombia",
                body = "Según Cenicafé, en Colombia el proceso poscosecha más común es el beneficio por vía húmeda, que da origen a los llamados cafés suaves lavados. La Organización Internacional del Café usa el grupo 'Suaves Colombianos' en sus indicadores de precios, y Colombia es su principal origen. Taza limpia, acidez brillante y cuerpo medio son la firma clásica de ese proceso. La producción cafetera de Colombia es de café arábica, y la mayor parte se procesa por vía húmeda: se despulpa, se fermenta, se lava y se seca. Por eso en el mercado internacional se habla de los 'suaves colombianos'. El robusta, que crece en tierras bajas, no está prohibido, pero la Federación no lo recomienda para las zonas cafeteras andinas.",
                related = new[] { "ben_fermentacion", "ben_secado" } },
            new WikiEntry { id = "ben_honey", category = "Beneficio", title = "Honey: amarillo, rojo y negro", year = "", place = "Costa Rica (origen del nombre)",
                body = "En el proceso honey (miel) se despulpa la cereza pero no se fermenta ni se lava: el grano se seca con parte o todo el mucílago pegado. Se popularizó en los micro beneficios de Costa Rica, que lo bautizaron por colores: el amarillo conserva menos mucílago y se seca más rápido, mientras el rojo y el negro conservan más y se secan más despacio. Ojo: cada beneficio define sus colores a su manera, y el manejo del secado pesa tanto como el mucílago que se deja.",
                related = new[] { "ben_natural", "ben_fermentacion" } },
            new WikiEntry { id = "ben_natural", category = "Beneficio", title = "Natural: secar la cereza entera", year = "", place = "",
                body = "En el proceso natural, el más antiguo, la cereza se seca entera, con pulpa y mucílago, y solo después se le quita la cáscara seca. Es tradicional en Etiopía, Yemen y Brasil, y suele dar tazas más frutales, dulces y con más cuerpo. Exige mucho cuidado: en climas húmedos la cereza puede enmohecerse o sobrefermentarse antes de secar.",
                related = new[] { "ben_honey", "ben_secado" } },
            new WikiEntry { id = "ben_anaerobico", category = "Beneficio", title = "Anaeróbico, maceración carbónica y choque térmico", year = "2015", place = "Seattle (campeonato); café de Colombia",
                body = "En la fermentación anaeróbica el café, en cereza o despulpado, se encierra en tanques o bolsas selladas sin oxígeno, a menudo con una válvula para liberar el gas que se forma. Al cambiar el ambiente cambian los microorganismos que trabajan y los compuestos que generan, lo que puede dar sabores intensos y poco usuales. Mal manejada, el resultado es una taza avinagrada o con sabor a alcohol. La maceración carbónica es una técnica tomada del vino: los frutos fermentan en un recipiente sellado lleno de dióxido de carbono. En 2015 el australiano Saša Šestić ganó el Campeonato Mundial de Baristas en Seattle con un café colombiano de variedad Sudan Rume, procesado en tanques de acero inoxidable sellados a los que se les inyectó CO2. Él contó que la idea nació de trabajar con un enólogo, y ese triunfo disparó la fiebre de los procesos experimentales. El choque térmico es una técnica de poscosecha surgida en el Cauca, asociada a la Finca El Paraíso. Tras la fermentación, el café pasa por un baño de agua caliente y luego por uno de agua fría; fuentes comerciales hablan de unos 40-50 °C y luego 5-15 °C, aunque no hay estudios científicos que fijen esos valores. Más que un proceso completo, es un paso adicional dentro de la vía húmeda que busca tazas muy aromáticas y limpias.",
                related = new[] { "ben_fermentacion", "ben_defectos" } },
            new WikiEntry { id = "ben_secado", category = "Beneficio", title = "Secado: entre 10 y 12 % de humedad", year = "", place = "",
                body = "El café recién lavado sale con más de la mitad de su peso en agua y hay que secarlo hasta que el pergamino quede entre 10 % y 12 % de humedad, como exige la norma de comercialización en Colombia. Por encima de 12 % el café se rechaza en el punto de compra. Por debajo de 10 % el caficultor pierde plata, porque vende menos peso. En la finca el secado solar se hace en patios, paseras, casa elbas de techo corredizo y marquesinas o secadores parabólicos cubiertos de plástico. Cenicafé recomienda el secador parabólico para fincas que producen menos de 500 arrobas de pergamino seco al año. Con capas de unos 2 cm, revolviendo al menos 4 veces al día y más de 5 horas de sol diario, el café lavado puede secarse en 3 a 7 días. Cuando no hay sol suficiente se usan silos o secadores mecánicos que soplan aire caliente con un ventilador. Cenicafé fija el límite en 50 °C, y entre las causas del grano cristalizado señala el aire de secado por encima de esa temperatura. Secar despacio y parejo protege los aromas; secar a la carrera los daña de forma irreversible.",
                related = new[] { "ben_trilla", "ben_almacenamiento" } },
            new WikiEntry { id = "ben_trilla", category = "Beneficio", title = "La trilla, la merma y las mallas", year = "", place = "",
                body = "La trilla quita el pergamino, esa cascarilla de papel que envuelve el grano, y deja el café verde o almendra. En la tabla de la Federación para factor 94, de una carga de 125 kg salen unos 93,09 kg de excelso y 8,16 kg de pasilla, con una merma del 19 % entre cascarilla y humedad. La pasilla, el grano defectuoso o pequeño que no alcanza calidad de exportación, se paga aparte y a menor precio, e históricamente se destinó al consumo interno. El café verde se clasifica por tamaño pasándolo por zarandas con huecos medidos en sesenta y cuatroavos de pulgada (1/64″ ≈ 0,4 mm). Según la Federación, el Supremo es malla 17 (unos 6,75 mm), el Extra malla 16, el Europa malla 15 y el UGQ malla 14, con pequeñas tolerancias de grano menor. Excelso es el nombre general del café verde colombiano de exportación; un grano grande no garantiza mejor sabor, pero un tamaño parejo ayuda a tostar uniforme.",
                related = new[] { "ben_defectos", "ben_factor_rendimiento" } },
            new WikiEntry { id = "ben_defectos", category = "Beneficio", title = "Defectos: negro, vinagre y cardenillo", year = "", place = "",
                body = "La norma colombiana agrupa los defectos en dos grupos: en el primero están los granos negros, vinagres y reposados o ámbar; en el segundo, cardenillos, flojos, decolorados y picados por insectos, entre otros. El negro suele venir de frutos caídos, sobremaduros o mal secados y ensucia la taza; el vinagre nace de fermentaciones pasadas o despulpado tardío y sabe agrio. El cardenillo es grano atacado por hongos por secado lento o rehumedecido, y deja notas a moho. La SCA clasifica el café verde revisando una muestra de 350 g. Para ser grado especialidad no puede tener ningún defecto de Categoría 1 (como grano negro completo, agrio completo, hongos o materia extraña) y máximo 5 defectos completos de Categoría 2. Algunos defectos se cuentan en grupo: 3 granos parcialmente negros equivalen a 1 defecto completo, y hacen falta 5 granos partidos o mordidos para sumar 1.",
                related = new[] { "ben_trilla", "cul_broca" } },
            new WikiEntry { id = "tos_fases", category = "Tostión", title = "Las fases del tueste y la reacción de Maillard", year = "1912", place = "",
                body = "Un tueste se divide en tres fases: en el secado el grano pierde agua y pasa de verde a amarillo; en la fase de Maillard se dora, aparecen aromas a pan y caramelo, y termina con el primer crack, un chasquido parecido al de las crispetas que suele sonar alrededor de 196 °C. Desde ahí empieza el desarrollo. Si se sigue hasta unos 224 °C llega el segundo crack, más suave y seguido, y los aceites empiezan a salir a la superficie del grano. La reacción de Maillard, descrita por el químico francés Louis-Camille Maillard en 1912, es la combinación de azúcares y aminoácidos con calor que dora el pan, la carne y el café. En el tueste genera las melanoidinas que dan el color café y cientos de compuestos aromáticos: en el café tostado se han identificado más de 800 compuestos volátiles. El café verde, en cambio, huele a pasto y a legumbre.",
                related = new[] { "tos_primer_crack", "tos_desarrollo" } },
            new WikiEntry { id = "tos_primer_crack", category = "Tostión", title = "El primer crack", year = "", place = "",
                body = "Un tueste se divide en tres fases: en el secado el grano pierde agua y pasa de verde a amarillo; en la fase de Maillard se dora, aparecen aromas a pan y caramelo, y termina con el primer crack, un chasquido parecido al de las crispetas que suele sonar alrededor de 196 °C. Desde ahí empieza el desarrollo. Si se sigue hasta unos 224 °C llega el segundo crack, más suave y seguido, y los aceites empiezan a salir a la superficie del grano.",
                related = new[] { "tos_fases", "tos_desarrollo" } },
            new WikiEntry { id = "tos_desarrollo", category = "Tostión", title = "Tiempo de desarrollo: el porcentaje que lo cambia todo", year = "", place = "",
                body = "Los tostadores miden la proporción del tiempo de desarrollo (DTR): el tiempo después del primer crack dividido entre el tiempo total del tueste, que en café de especialidad suele estar entre 15 % y 25 %. Muy corto, el café queda subdesarrollado, con notas a pasto, cereal y acidez agresiva; muy largo, se vuelve plano, amargo y con sabor a tostado. Por eso se busca que la tasa de aumento de temperatura (RoR) vaya bajando de forma suave.",
                related = new[] { "tos_primer_crack", "tos_niveles" } },
            new WikiEntry { id = "tos_niveles", category = "Tostión", title = "Claro, medio u oscuro: el grano adelgaza", year = "", place = "",
                body = "Durante el tueste el café pierde peso, sobre todo por evaporación de agua: los tuestes claros y medios de especialidad suelen perder entre 11 % y 16 %, y los oscuros pueden pasar de 18 %. El grano además se infla y se vuelve menos denso. El color se mide con equipos como el Agtron: entre más alto el número, más claro el tueste.",
                related = new[] { "tos_desarrollo", "tos_reposo" } },
            new WikiEntry { id = "tos_reposo", category = "Tostión", title = "Dejar reposar: el café respira CO2", year = "", place = "",
                body = "El café recién tostado guarda dióxido de carbono que suelta durante días, aunque la mayor parte sale en las primeras 24 a 48 horas. Por eso se empaca en bolsas con válvula de una vía, que dejan salir el gas sin dejar entrar oxígeno, y muchos tostadores recomiendan reposar 3 a 7 días para filtrados y 7 a 14 para espresso. Ese CO2 es el que forma el 'bloom' en una AeroPress y la costra en la catación.",
                related = new[] { "tos_niveles", "pre_aeropress_metodos" } },
            new WikiEntry { id = "cat_protocolo_sca", category = "Catación", title = "El ritual de la catación", year = "", place = "",
                body = "En el protocolo de catación de la SCA se usan 8,25 g de café por cada 150 ml de agua, molido de forma que entre 70 % y 75 % pase por un tamiz de malla 20 (850 micras), y agua a 93 °C. Primero se huele la fragancia en seco antes de 15 minutos de molido; luego se vierte el agua, se forma una costra y a los 3-5 minutos (típicamente a los 4) se rompe con la cuchara, revolviendo tres veces, para oler el aroma. Se empieza a probar cuando baja a unos 71 °C y se sigue evaluando hasta unos 21 °C, con 5 tazas por muestra para comprobar uniformidad. Para catar, la muestra se tuesta claro a medio en 8 a 12 minutos y se cata entre 8 y 24 horas después del tueste. El protocolo SCA de 2004 apuntaba a un color cercano a 58 en grano y 63 en molido en la escala Agtron 'Gourmet'. Así todos los catadores comparan cafés tostados de forma parecida, sin que un tueste oscuro tape defectos ni virtudes del origen. Catar exige sorber el café de la cuchara con fuerza y haciendo ruido, para rociarlo por toda la boca y llevar los aromas a la nariz por vía retronasal. Entre taza y taza se enjuaga la cuchara, y muchos catadores escupen para mantener el paladar fresco en sesiones largas. La acidez, el cuerpo y el balance se juzgan con el café aún caliente, y el dulzor, la uniformidad y la taza limpia cuando se acerca a temperatura ambiente.",
                related = new[] { "cat_rueda_sabores", "cat_puntaje_especialidad" } },
            new WikiEntry { id = "cat_rueda_sabores", category = "Catación", title = "La Rueda de Sabores del Catador", year = "1995 / 2016", place = "",
                body = "La primera Rueda de Sabores del Catador de Café la publicó la SCAA en 1995, y en 2016 se rediseñó con World Coffee Research a partir de su Léxico Sensorial, desarrollado en la Universidad Estatal de Kansas, que describe 110 atributos de sabor, aroma y textura. Se lee del centro hacia afuera: el anillo interno tiene nueve categorías (floral, frutal, ácido/fermentado, verde/vegetal, otros, tostado, especias, nueces/cacao y dulce). Cada una se vuelve más específica hacia afuera, como de 'frutal' a 'frutos rojos' y luego a 'mora'.",
                related = new[] { "cat_protocolo_sca", "cat_q_grader" } },
            new WikiEntry { id = "cat_q_grader", category = "Catación", title = "Q Grader: el catador certificado", year = "2025", place = "",
                body = "El Q Grader es una certificación internacional de catadores creada por el Coffee Quality Institute (CQI) a comienzos de los años 2000; su examen clásico tenía unas 20 pruebas de olfato, triangulación, catación, clasificación de verde y tostado, y ácidos orgánicos. En las pruebas de olfato se usaba Le Nez du Café, un kit francés de 36 frascos de aromas agrupados en enzimáticos, de caramelización, de destilación seca y defectos aromáticos. Desde el 1 de octubre de 2025 el programa lo maneja la SCA, que lo reformuló sobre la CVA, y quienes ya tenían licencia deben presentar el nuevo examen cuando se les venza.",
                related = new[] { "cat_protocolo_sca", "cat_puntaje_especialidad" } },
            new WikiEntry { id = "cat_puntaje_especialidad", category = "Catación", title = "La escala de 100 puntos y los 80 de especialidad", year = "2004", place = "",
                body = "Durante dos décadas el formulario SCA de 2004 fue el estándar mundial: evalúa fragancia/aroma, sabor, sabor residual, acidez, cuerpo, balance, uniformidad, taza limpia, dulzor y puntaje general. Los atributos de calidad se califican de 6 a 10 en pasos de 0,25; uniformidad, taza limpia y dulzor dan 2 puntos por taza en 5 tazas, y los defectos restan 2 (contaminación) o 4 (falla) por taza afectada. Desde 80 puntos el café es de especialidad: 80-84,99 muy bueno, 85-89,99 excelente y 90 o más, excepcional. En la escala de catación de la SCA, que va de 0 a 100 puntos, un café se considera de especialidad cuando saca 80 puntos o más y no tiene defectos primarios. La SCA actual nació en 2017 de la unión de la asociación estadounidense (SCAA, fundada en 1982) y la europea (SCAE). En noviembre de 2024 la SCA adoptó la Evaluación del Valor del Café (CVA) como su estándar de catación, reemplazando el protocolo y el formulario de 2004. Separa lo que el café es de lo que al catador le gusta: la evaluación descriptiva marca intensidades de 0 a 15 y descriptores de una lista, y la afectiva califica la impresión de calidad de 1 a 9; además hay evaluaciones físicas y extrínsecas (origen, certificaciones, historia). En 2025 la SCA anunció una alianza con la Federación Nacional de Cafeteros para impulsar la CVA en Colombia.",
                related = new[] { "cat_protocolo_sca", "hist_olas_especialidad" } },
            new WikiEntry { id = "pre_extraccion_tds", category = "Preparación", title = "Extraer: qué tanto sale y qué tan fuerte queda", year = "", place = "",
                body = "Extraer es disolver en el agua una parte del grano molido. Un grano tostado tiene como máximo cerca de un 30 % de materia soluble, pero sacarla toda daría una bebida amarga y astringente. Para filtrados, el rango de referencia es extraer entre el 18 % y el 22 % del peso del café seco. Los sólidos disueltos totales (TDS) miden la concentración. Un filtrado equilibrado anda entre 1,15 % y 1,35 %, o sea que más del 98 % de la taza es agua, mientras que un espresso suele estar entre 8 % y 12 %. Los baristas lo miden con un refractómetro, que calcula los sólidos según cuánto se desvía la luz al pasar por una gota de café. Un café puede estar bien extraído y aun así quedar muy fuerte o muy aguado. La fuerza depende sobre todo de la proporción entre café y agua, mientras que la extracción depende de la molienda, el tiempo, la temperatura y la agitación. Si sabe rico pero 'pesado', se le agrega agua (bypass); si sabe agrio, hay que extraer más, no echarle más café.",
                related = new[] { "pre_carta_control", "pre_molienda" } },
            new WikiEntry { id = "pre_carta_control", category = "Preparación", title = "La carta de control y la Copa de Oro", year = "década de 1950", place = "Estados Unidos",
                body = "En los años cincuenta, Ernest Earl Lockhart, científico de alimentos y director del Coffee Brewing Institute en Estados Unidos, propuso medir la calidad de una taza con dos números: la concentración (sólidos disueltos totales, TDS) y el porcentaje de extracción. De ahí salió la carta de control de preparación, una cuadrícula de nueve casillas en la que el centro marca la taza equilibrada. Todavía hoy es la base con la que los baristas 'calibran' una receta. La SCA toma como referencia 55 gramos de café por litro de agua, con una tolerancia de más o menos 10 %, lo que equivale más o menos a una relación 1:18. Muchos baristas de especialidad trabajan los filtrados entre 1:15 y 1:17. Pesar el café y el agua en gramos con una balanza es el primer paso para dejar de adivinar. Lo primero que se disuelve son los ácidos y los compuestos salados, después los azúcares y los compuestos dulces, y de últimas los más amargos y astringentes. Por eso un café sub-extraído sabe agrio, salado y aguado, y uno sobre-extraído sabe amargo, áspero y deja la boca reseca. La gracia está en parar justo cuando ya llegó el dulzor.",
                related = new[] { "pre_extraccion_tds", "pre_temperatura" } },
            new WikiEntry { id = "pre_molienda", category = "Preparación", title = "La molienda manda", year = "", place = "",
                body = "Entre más fina la molienda, más superficie de contacto y más rápido se extrae, pero también le pone más resistencia al paso del agua. Un molino de fresas da partículas más parejas que uno de cuchillas. Los 'finos' se sobre-extraen y los pedazos grandes se quedan cortos, y esa mezcla puede dar una taza amarga y ácida al mismo tiempo.",
                related = new[] { "pre_extraccion_tds", "pre_temperatura" } },
            new WikiEntry { id = "pre_temperatura", category = "Preparación", title = "Temperatura, tiempo y agitación", year = "", place = "",
                body = "La temperatura acelera la disolución: con agua más caliente se extrae más en menos tiempo. Para filtrados, la SCA recomienda unos 93 °C, con un margen de 3 °C para arriba o para abajo. Los tuestes claros, más densos, suelen pedir agua más caliente, y los oscuros, más solubles, aguantan agua más fría. Entre más tiempo esté el agua en contacto con el café, más se extrae. Revolver o hacer remolinos renueva el agua alrededor de cada partícula, y eso también acelera la extracción. Por eso dos personas con la misma receta pueden sacar tazas distintas: la mano que revuelve también es una variable.",
                related = new[] { "bog_altitud_ebullicion", "pre_molienda" } },
            new WikiEntry { id = "pre_aeropress_metodos", category = "Preparación", title = "AeroPress: estándar, invertida, papel o metal", year = "", place = "Bogotá",
                body = "La AeroPress es un cilindro con un émbolo de sello de caucho. El café y el agua se mezclan en la cámara (inmersión) y después el aire que comprime el émbolo empuja la bebida a través de un filtro de papel de unos 63,5 mm. La presión es baja, nada que ver con los 9 bar de una máquina de espresso, pero la preparación es rápida y la limpieza muy fácil. Las instrucciones oficiales de AeroPress dicen que se revuelva unos 10 segundos y después se presione suavemente durante 20 a 30 segundos. La marca recomienda agua a 80 °C (175 °F) porque fue la temperatura que más les gustó a sus catadores. En Bogotá es facilito cumplirla: basta con dejar enfriar un poco el agua que hirvió a 91 °C. En el método invertido se pone primero el émbolo y la AeroPress se usa boca abajo, así no gotea nada mientras el café está en inmersión. Al final se enrosca la tapa con el filtro y se voltea con cuidado sobre la taza, que es justo el momento en que más se riega el café. Es muy popular en competencias porque deja controlar con precisión el tiempo de contacto. El filtro de papel retiene casi todos los aceites y las partículas finas, y deja una taza limpia y brillante. También atrapa diterpenos como el cafestol, que se asocian con el aumento del colesterol. El filtro metálico deja pasar aceites y finos: más cuerpo y textura, pero algo de sedimento.",
                related = new[] { "hist_aeropress_2005", "comp_wac" } },
            new WikiEntry { id = "pre_agua", category = "Preparación", title = "El agua: el 98 % de tu taza", year = "2009", place = "Bogotá / La Calera (Cundinamarca)",
                body = "El estándar de agua para café de la SCA apunta a unos 150 mg/L de sólidos disueltos (rango de 75 a 250), dureza cálcica cercana a 68 mg/L, alcalinidad alrededor de 40 mg/L, pH 7 y nada de cloro. El agua destilada sabe plana y extrae mal, y el agua muy dura apaga los sabores y llena las máquinas de sarro. El calcio y el magnesio (la dureza) ayudan a 'agarrar' compuestos de sabor y suben la extracción. Los bicarbonatos (la alcalinidad) funcionan como amortiguador: neutralizan ácidos, así que con mucha alcalinidad un café brillante sabe plano y con muy poca puede quedar agrio y punzante. Por eso muchos baristas de competencia preparan su propia agua mineralizando agua pura. Cerca del 80 % del agua de Bogotá viene del sistema Chingaza y se potabiliza en la planta Francisco Wiesner, en La Calera; el resto sale de otras plantas, como Tibitoc. Como toda agua de acueducto, lleva cloro para desinfectarla, y conviene quitárselo con un filtro de carbón antes de hacer café. Antes de fijar recetas, lo serio es medir la dureza y la alcalinidad con un kit, porque cambian según la planta que surte cada barrio.",
                related = new[] { "pre_temperatura", "bog_altitud_ebullicion" } },
            new WikiEntry { id = "pre_bebidas_colombianas", category = "Preparación", title = "Tinto, perico, pintado y carajillo", year = "", place = "Colombia",
                body = "En Colombia 'tinto' es el café negro, sin leche, casi siempre servido en pocillo pequeño. Se vende en termos en la calle, en las oficinas y en las esquinas, y ofrecerlo es una de las formas más comunes de hospitalidad: '¿le provoca un tintico?'. Durante décadas buena parte del tinto callejero se hizo con café de menor calidad y bastante azúcar, porque lo mejor se exportaba, y eso es justo lo que la cultura de especialidad quiere cambiar. Pedir café en Colombia tiene su propio vocabulario. El 'pintado' o 'pintadito' es un tinto con un chorrito de leche, muy típico de Antioquia y del Eje Cafetero, mientras que en Bogotá es común pedir un 'perico', un café con leche, aunque cuánta leche lleva depende de quién lo sirva. El café con leche, grande y espumoso, no puede faltar en el desayuno. El carajillo colombiano es un tinto con un toque de licor, casi siempre aguardiente o ron. Es típico de ciudades frías como Bogotá, Manizales y Pasto, y de pueblos de clima frío como Villa de Leyva.",
                related = new[] { "bog_tinto", "pre_metodos_filtrado" } },
            new WikiEntry { id = "pre_metodos_filtrado", category = "Preparación", title = "Colador de tela, goteo, prensa y moka", year = "1908-2004", place = "Colombia",
                body = "Antes de los filtros de papel, en muchas casas colombianas el café se hacía en olleta: se calentaba el agua, a veces aguapanela, se le echaba el café molido y después se pasaba por un colador de tela, una especie de 'media' de algodón. La tela retiene el sedimento pero deja pasar parte de los aceites. Tradicionalmente se lava solo con agua, sin jabón, para que no le queden olores. En 1908, en Dresde (Alemania), Melitta Bentz patentó un portafiltro con papel secante, el origen del filtro de papel moderno. En 1941 el químico alemán Peter Schlumbohm, radicado en Estados Unidos, creó la Chemex, una jarra de vidrio con forma de reloj de arena y un filtro grueso que da una taza muy limpia. En 2004 la japonesa Hario lanzó el V60, un cono de 60 grados con estrías en espiral y un solo agujero grande, en el que el vertido del barista controla el flujo; el Kalita Wave, en cambio, tiene fondo plano y tres agujeros pequeños, y perdona más los errores. Aunque le dicen 'francesa', el diseño moderno con émbolo y malla sellada lo patentaron en 1929 los italianos Attilio Calimani y Giulio Moneta, después de un antecedente francés de 1852. Es un método de inmersión total, con molienda gruesa, unos 4 minutos de contacto y un filtro metálico que deja pasar los aceites. Por eso la taza sale con mucho cuerpo y algo de sedimento. La cafetera moka, que Bialetti popularizó con su Moka Express de 1933, usa la presión del vapor que se forma en la base para subir el agua a través del café. Esa presión ronda 1 a 2 bar, muy lejos de los 9 bar del espresso, así que sale un café concentrado e intenso pero sin la crema de una máquina. Para evitar el sabor a quemado, se arranca con agua ya caliente y se retira del fuego apenas empieza a borbotear.",
                related = new[] { "pre_bebidas_colombianas", "pre_espresso" } },
            new WikiEntry { id = "pre_espresso", category = "Preparación", title = "Espresso: 9 bar y unos 25 a 30 segundos", year = "", place = "Italia",
                body = "El espresso se hace empujando agua caliente a unos 9 bar de presión a través de una pastilla compacta de café molido fino. La definición clásica del Instituto Nacional del Espresso Italiano habla de unos 7 g de café, agua hacia los 88 °C, 9 bar y 25 ml en unos 25 segundos. En la especialidad de hoy es común usar 18 g de café para sacar unos 36 g de bebida (proporción 1:2) en 25 a 30 segundos.",
                related = new[] { "hist_espresso", "pre_metodos_filtrado" } },
            new WikiEntry { id = "comp_wac", category = "Competencias", title = "El Campeonato Mundial de AeroPress", year = "2008", place = "Oslo, Noruega",
                body = "El Campeonato Mundial de AeroPress (WAC) arrancó en 2008 en Oslo, Noruega, en un espacio pequeño, con apenas tres competidores. Hoy es una organización independiente que se maneja desde Melbourne, Australia, y tiene campeonatos nacionales en más de 60 países. Su espíritu es comunitario y fiestero: cualquiera con una AeroPress puede soñar con llegar. En el formato clásico del WAC, tres competidores preparan al mismo tiempo con el mismo café y entregan sus tazas a ciegas a un panel de tres jueces. Cuando se da la señal, cada juez señala con el dedo su taza favorita, y el que reciba más votos sigue en la llave de eliminación. Las reglas ponen límites de tiempo y de dosis, y el formato se ha ido ajustando con los años.",
                related = new[] { "hist_aeropress_2005", "comp_wbc" } },
            new WikiEntry { id = "comp_wbc", category = "Competencias", title = "El Campeonato Mundial de Baristas", year = "2000", place = "Montecarlo, Mónaco",
                body = "El Campeonato Mundial de Baristas (WBC) se hizo por primera vez en el año 2000 en Montecarlo, con más o menos una docena de competidores. En cada presentación el barista prepara espressos, bebidas con leche y una bebida de autor para los jueces sensoriales, mientras los jueces técnicos evalúan su técnica, su limpieza y el manejo de la estación, todo contra el reloj. En junio de 2011 Bogotá fue la sede del Campeonato Mundial de Baristas, la primera vez que se hizo en un país productor de café. Ganó un barista salvadoreño: el primer campeón mundial de un país de origen, con cafés de su tierra. Fue la prueba de que los países que cultivan el café también pueden liderar su preparación.",
                related = new[] { "comp_wac", "comp_brewers_cup" } },
            new WikiEntry { id = "comp_brewers_cup", category = "Competencias", title = "La Copa Mundial de Filtrados", year = "2011", place = "Maastricht, Países Bajos",
                body = "El World Brewers Cup, la competencia mundial de métodos manuales de filtrado, se hizo por primera vez en 2011 en Maastricht (Países Bajos). Tiene una ronda obligatoria, en la que todos preparan el mismo café, y una ronda abierta con café y método a elección del competidor, que además debe explicarles su preparación a los jueces.",
                related = new[] { "comp_wbc", "pre_metodos_filtrado" } },
            new WikiEntry { id = "hist_ceremonia_etiope", category = "Historia", title = "La ceremonia etíope del café", year = "Tradición viva", place = "Etiopía",
                body = "En Etiopía el café se toma en una ceremonia: los granos verdes se tuestan en una sartén frente a los invitados, se muelen en mortero y se preparan en una jarra de barro llamada jebena. Se sirven tres rondas, la última conocida como 'baraka' (bendición). Es un ritual de hospitalidad y comunidad, no un café al paso.",
                related = new[] { "hist_kaldi", "hist_yemen_moca" } },
            new WikiEntry { id = "hist_bach", category = "Historia", title = "La Cantata del café de Bach", year = "c. 1732-1735", place = "Leipzig, Alemania",
                body = "Johann Sebastian Bach compuso la 'Cantata del café' (BWV 211), una pequeña ópera cómica sobre una muchacha que no quiere dejar el café aunque su papá la amenace. Se interpretaba en el Café Zimmermann de Leipzig, donde se hacían conciertos.",
                related = new[] { "hist_europa_cafes", "hist_cafeina" } },
            new WikiEntry { id = "hist_cafeina", category = "Historia", title = "Goethe, Runge y la cafeína", year = "1819", place = "Jena, Alemania",
                body = "En 1819 el químico alemán Friedlieb Ferdinand Runge aisló la cafeína por primera vez. Lo hizo animado por el escritor Goethe, que le regaló unos granos de café para que averiguara qué tenían.",
                related = new[] { "hist_bach", "cul_bajo_cafeina" } },
            new WikiEntry { id = "hist_colonizacion_antioquena", category = "Historia", title = "Arrieros, fincas pequeñas y cables aéreos", year = "Siglo XIX - primera mitad del XX", place = "Antioquia, Caldas, Risaralda, Quindío",
                body = "La colonización antioqueña abrió monte hacia el sur y fundó muchos pueblos de Caldas, Risaralda y Quindío. A comienzos del siglo XX el café pasó de las grandes haciendas a fincas familiares: hacia 1932 había cerca de 150.000 fincas cafeteras, la mayoría de menos de diez hectáreas. El café se volvió el principal producto de exportación del país y movió arrieros, ferrocarriles y hasta el cable aéreo Manizales-Mariquita, inaugurado en los años veinte. Durante el siglo XIX, familias antioqueñas migraron hacia el sur tumbando monte y fundando pueblos; Manizales (1849) y Armenia (1889) nacieron de ese movimiento. Con ellas llegaron el café, la arriería y las casas de bahareque, hechas de guadua y tierra, con balcones y puertas de colores. Esa arquitectura es hoy parte de la identidad del Eje Cafetero.",
                related = new[] { "col_arrieros", "col_cable_aereo" } },
            new WikiEntry { id = "hist_pacto_cuotas", category = "Historia", title = "El pacto de cuotas y su ruptura", year = "1962-1989", place = "Londres (sede de la OIC) / mundo",
                body = "En 1962 se firmó el Acuerdo Internacional del Café, que repartía cuotas de exportación para estabilizar precios, y para manejarlo se creó la Organización Internacional del Café en Londres. En julio de 1989 el sistema de cuotas se rompió y los precios se fueron al piso, una crisis durísima para las familias cafeteras. Desde 2015 la OIC celebra cada 1 de octubre el Día Internacional del Café.",
                related = new[] { "hist_fnc_1927", "hist_olas_especialidad" } },
            new WikiEntry { id = "hist_bebida_nacional", category = "Historia", title = "El café, bebida nacional", year = "2025", place = "Colombia",
                body = "Con la Ley 2504 del 28 de julio de 2025, Colombia declaró al café de Colombia producto y bebida nacional por su importancia histórica, social, económica y cultural. La misma ley creó un programa voluntario de aportes para la vejez de los caficultores. Hoy unas 550.000 familias cultivan café en más de 600 municipios de 22 departamentos, y la mayoría son pequeños productores con pocas hectáreas. En 2024 el país produjo cerca de 14 millones de sacos de 60 kilos. Gracias a sus montañas y su cercanía al ecuador, en Colombia hay cosecha casi todo el año, repartida entre la cosecha principal y la 'mitaca'.",
                related = new[] { "bog_tinto", "col_familias" } },
            new WikiEntry { id = "hist_taza_excelencia", category = "Competencias", title = "Taza de la Excelencia y campeonatos", year = "1999-2005", place = "Brasil, Montecarlo, Colombia",
                body = "En 1999 Brasil organizó la primera Cup of Excellence (Taza de la Excelencia), una competencia que premia los mejores lotes de un país y los subasta por internet. En 2000 se hizo en Montecarlo el primer Campeonato Mundial de Baristas. Colombia celebró su primera Taza de la Excelencia en 2005, y muchos de los lotes premiados venían del Huila.",
                related = new[] { "comp_wbc", "cat_puntaje_especialidad" } },
            new WikiEntry { id = "col_arrieros", category = "Colombia", title = "Arrieros: el café a lomo de mula", year = "siglo XIX y comienzos del XX", place = "Antioquia y Eje Cafetero",
                body = "Antes de las carreteras, el café bajaba de la montaña a lomo de mula. Los arrieros guiaban recuas por caminos de herradura hasta los puertos del río Magdalena o las estaciones del tren. El arriero, con su carriel, su poncho y su sombrero, se volvió un símbolo de la cultura paisa.",
                related = new[] { "hist_colonizacion_antioquena", "col_cable_aereo" } },
            new WikiEntry { id = "col_cable_aereo", category = "Colombia", title = "El cable aéreo Manizales–Mariquita", year = "1922", place = "Manizales (Caldas) – Mariquita (Tolima)",
                body = "Entre Manizales y Mariquita funcionó un cable aéreo de unos 72 km, terminado en 1922 y construido por una compañía inglesa. Bajaba café en vagonetas colgantes hacia el valle del Magdalena para seguir por el río hasta el Caribe. Tenía 22 estaciones y cientos de torres metálicas: una obra enorme para su época.",
                related = new[] { "col_arrieros", "hist_colonizacion_antioquena" } },
            new WikiEntry { id = "col_resguardos_sur", category = "Colombia", title = "Café en resguardos del sur", year = "", place = "Cauca y sur del Tolima",
                body = "En el Cauca y en el sur del Tolima, comunidades indígenas como los nasa y los misak cultivan café en sus territorios, casi siempre en pequeñas parcelas junto a la huerta familiar. El trabajo colectivo de la minga es parte de su forma de producir. Varias asociaciones de la región, incluidas organizaciones indígenas, venden hoy cafés especiales.",
                related = new[] { "col_indigenas_sierra", "col_familias" } },
            new WikiEntry { id = "col_huila", category = "Colombia", title = "Huila, primer productor", year = "", place = "Huila",
                body = "Desde hace unos quince años, el Huila es el departamento que más café produce en Colombia: casi uno de cada cinco sacos del país sale de allí. Lo siguen departamentos como Antioquia, Tolima y Cauca. El sur del país, que antes no era el centro de la caficultura, hoy lidera en volumen y en cafés especiales.",
                related = new[] { "ben_fermentacion", "col_familias" } },
            new WikiEntry { id = "col_familias", category = "Colombia", title = "Un país de pequeños caficultores", year = "2024-2025", place = "Colombia",
                body = "La caficultura colombiana es de familias: alrededor de 550.000 familias cultivan café en 23 departamentos y cerca de 600 municipios. Más o menos el 96% de los productores tiene menos de 5 hectáreas en café, y la mitad tiene menos de una hectárea. Por eso cada decisión de una finca pequeña cuenta.",
                related = new[] { "col_huila", "hist_bebida_nacional" } },
            new WikiEntry { id = "col_cafe_todo_el_ano", category = "Colombia", title = "Café fresco casi todo el año", year = "", place = "Colombia",
                body = "Gracias a su geografía, Colombia saca café fresco casi todo el año. En el norte (Santander, Norte de Santander, Sierra Nevada) suele haber una sola cosecha, hacia final de año. En el centro hay dos picos, uno entre abril y junio y otro entre septiembre y diciembre. En el sur (Nariño, Cauca) la cosecha principal tiende a caer en el primer semestre.",
                related = new[] { "col_cosecha_mitaca", "col_cordilleras" } },
            new WikiEntry { id = "cul_variedades_resistentes", category = "Cultivo", title = "Colombia, Castillo, Tabi y Cenicafé 1", year = "2005 / 2024", place = "Colombia",
                body = "En 2005 Cenicafé entregó la variedad Castillo, también derivada de Caturra por Híbrido de Timor, resistente a la roya, productiva y de buen tamaño de grano, junto con siete componentes regionales: El Rosario, Naranjal, Paraguaicito, La Trinidad, Pueblo Bello, Santa Bárbara y El Tambo. Fue la gran protagonista de la renovación de cafetales tras la epidemia de roya. En 2024 Cenicafé presentó Castillo 2.0, que suma nuevas fuentes de resistencia de otros arábicos y de Coffea canephora. Tabi, entregada por Cenicafé en 2002, es una variedad de porte alto, derivada de Híbrido de Timor con Típica y Borbón, pensada para fincas tradicionales con sombrío; es resistente a la roya y tiene buen tamaño de grano y calidad en taza. Cenicafé 1, entregada en 2016, es de porte bajo como el Caturra, muy productiva y resistente tanto a la roya como a la antracnosis de los frutos (CBD), una enfermedad presente en África pero no en Colombia.",
                related = new[] { "cul_roya", "hist_epidemia_roya_castillo" } },
            new WikiEntry { id = "cul_variedades_exoticas", category = "Cultivo", title = "Geisha, Pink Bourbon, Wush Wush y Sidra", year = "1930s / 1953 / 2004", place = "Etiopía / Costa Rica / Panamá",
                body = "La Geisha o Gesha viene del bosque de Gori Gesha, en el suroccidente de Etiopía, de donde se recolectó en la década de 1930. Pasó por Tanzania, llegó al CATIE en Costa Rica en 1953 y de ahí a Panamá, donde en 2004 un lote deslumbró en la subasta 'Best of Panama' por sus notas a jazmín y bergamota. Es de porte alto, ramas frágiles y poca producción, pero hoy está entre los cafés más cotizados del mundo. El llamado Pink Bourbon tiene cerezas de un rosado anaranjado y se hizo famoso en fincas del Huila, en el sur de Colombia. Por su nombre se creía que era un cruce de Borbón rojo y amarillo, pero análisis genéticos encargados por importadores en 2017 y 2023 indican que sería una variedad de origen etíope, sin relación clara con el Borbón. Es muy buscado en los cafés especiales por su taza floral y frutal. Wush Wush es una variedad tradicional del pueblo de Wushwush, cerca del bosque de Bonga en Kafa (Etiopía), que llegó a Sudamérica en los años noventa y hoy se cultiva en fincas colombianas. Sidra es popular en Ecuador y en competencias, pero su origen se discute: unos la consideran un cruce de Típica y Borbón y otros una selección etíope. Java, pese a su nombre, es una selección de origen etíope que pasó por la isla de Java y por Camerún antes de llegar a Centroamérica.",
                related = new[] { "cul_variedades", "cul_maragogipe" } },
            new WikiEntry { id = "cul_maragogipe", category = "Cultivo", title = "Maragogipe: el grano elefante", year = "1870", place = "Bahía, Brasil",
                body = "El Maragogipe es una mutación natural de la Típica descubierta hacia 1870 cerca de Maragogipe, en Bahía, Brasil. Tiene hojas, cerezas y granos enormes, por lo que le dicen 'grano elefante', pero produce muy poco. Por su tamaño exige ajustar la tostión y la molienda.",
                related = new[] { "cul_variedades", "cul_variedades_exoticas" } },
            new WikiEntry { id = "cul_bajo_cafeina", category = "Cultivo", title = "Laurina y Eugenioides: poca cafeína natural", year = "", place = "La Reunión / África oriental / Colombia",
                body = "La Laurina o Bourbon Pointu es una mutación del Borbón de la isla La Reunión, con forma de arbolito de Navidad y granos puntiagudos, que tiene más o menos la mitad de la cafeína de un arábica común. Coffea eugenioides no es una variedad sino otra especie, uno de los ancestros del arábica: tiene muy poca cafeína, frutos pequeños y una taza dulce. Algunos productores colombianos la cultivan para el mercado de cafés especiales.",
                related = new[] { "cul_variedades_exoticas", "hist_cafeina" } },
            new WikiEntry { id = "cul_stenophylla", category = "Cultivo", title = "Stenophylla, el café que aguanta calor", year = "2021", place = "Sierra Leona / África Occidental",
                body = "Coffea stenophylla es una especie silvestre de África Occidental (Guinea, Sierra Leona y Costa de Marfil) que se creía casi perdida y fue redescubierta en Sierra Leona. Un estudio publicado en 2021 en la revista Nature Plants mostró que crece con temperaturas medias anuales entre 6,2 y 6,8 °C más altas que el arábica, y que su taza se parece a la de un arábica de buena calidad. Es una de las grandes esperanzas frente al cambio climático.",
                related = new[] { "cul_arabica_robusta", "cul_clima_ideal" } },
            new WikiEntry { id = "cul_ojo_de_gallo", category = "Cultivo", title = "Ojo de gallo y mal rosado", year = "", place = "Cordillera Oriental, Nariño, Cauca",
                body = "El ojo de gallo, también llamado gotera, lo causa el hongo Mycena citricolor y forma manchas redondas en hojas y frutos, que terminan cayéndose. Se dispara con lluvias frecuentes, humedad relativa por encima del 80 %, neblina, poco sol y sombrío muy denso. En Colombia afecta sobre todo la vertiente oriental de la cordillera Oriental, el piedemonte llanero y amazónico, Nariño y Cauca; se maneja regulando el sombrío y mejorando la aireación. El mal rosado lo causa el hongo Corticium salmonicolor, que forma en las ramas un micelio como de telaraña que pasa de blanco a rosado salmón. El hongo estrangula la rama, las hojas se amarillean y se secan como quemadas, por eso en algunas zonas le dicen 'brasa'. Aparece en épocas muy lluviosas y en cafetales densos y mal aireados; se controla podando y sacando las ramas enfermas, regulando la sombra y mejorando la ventilación.",
                related = new[] { "cul_roya", "cul_clima_ideal" } },
            new WikiEntry { id = "cul_suelo", category = "Cultivo", title = "Suelos ácidos y volcánicos", year = "", place = "Eje Cafetero",
                body = "El café prefiere suelos sueltos, profundos, con buena materia orgánica y ligeramente ácidos, con un pH que normalmente se maneja alrededor de 5,0 a 5,5. En buena parte del Eje Cafetero los suelos se formaron sobre cenizas volcánicas, que retienen agua y son muy fértiles. Cuando el suelo está demasiado ácido se corrige con cal, siempre guiándose por un análisis de suelos.",
                related = new[] { "cul_hidroponia", "col_cordilleras" } },
            new WikiEntry { id = "cul_polinizacion", category = "Cultivo", title = "Florecer y polinizar bajo techo", year = "", place = "Bogotá (bodega de Float Gardens)",
                body = "Bajo techo no llueve, así que para sincronizar la floración se puede simular un 'verano': reducir el riego algunas semanas sin dejar marchitar la planta y luego dar un riego abundante que imite el aguacero; las flores deberían abrir unos diez días después. Como el arábica es autofértil, no hacen falta abejas: basta el movimiento de aire de los ventiladores, sacudir suavemente las ramas o pasar un pincel por las flores para mejorar el cuajado. Con robusta, en cambio, habría que tener al menos dos clones distintos.",
                related = new[] { "cul_floracion", "cul_hidroponia" } },
            new WikiEntry { id = "ben_frio_bogota", category = "Beneficio", title = "En la bodega fría todo va más despacio", year = "", place = "Bogotá",
                body = "La fermentación es trabajo de microorganismos, y en frío trabajan más despacio: Cenicafé señala que en zonas frías el café necesita más tiempo de fermentación y recomienda mantener estable la temperatura. En una bodega de Bogotá, con promedios cercanos a 14 °C, un tanque tardaría más en llegar al punto de lavado que en una finca templada. Además, los cambios bruscos entre el día y la noche harían el proceso impredecible.",
                related = new[] { "ben_fermentacion", "bog_2600" } },
            new WikiEntry { id = "ben_pulpa", category = "Beneficio", title = "Menos agua y la pulpa como abono", year = "", place = "",
                body = "El beneficio tradicional llegó a gastar hasta 40 litros de agua por cada kilo de café pergamino seco. Cenicafé desarrolló tecnologías como Becolsub (0,7 a 1 litro por kilo) y Ecomill (0,3 a 0,5 litros por kilo), que reducen el consumo en más de 97,5 %. Aun así, las aguas mieles del lavado contaminan y deben tratarse antes de llegar a quebradas y ríos. La pulpa que sale del despulpado puede volverse abono: en Colombia se composta y se usa en lombricultura con lombriz roja californiana, que la transforma en lombricompuesto. Así lo que antes contaminaba vuelve al cafetal como nutrientes. De la cáscara seca de la cereza también se prepara una infusión conocida como cáscara.",
                related = new[] { "ben_despulpado", "ben_lavado" } },
            new WikiEntry { id = "ben_almacenamiento", category = "Beneficio", title = "El pergamino guarda olores", year = "", place = "",
                body = "El café pergamino seco absorbe humedad y olores con facilidad, por eso se guarda en bodegas secas y ventiladas, sobre estibas y lejos de combustibles, abonos o químicos. Si vuelve a humedecerse aparecen hongos y defectos como el cardenillo. Un lote excelente puede terminar sabiendo a gasolina si se almacena mal.",
                related = new[] { "ben_secado", "ben_trilla" } },
            new WikiEntry { id = "ben_factor_rendimiento", category = "Beneficio", title = "Factor de rendimiento y el Excelso", year = "2002", place = "",
                body = "En Colombia el pergamino seco se negocia por cargas de 125 kg, es decir, 10 arrobas de 12,5 kg. La calidad física se mide con el factor de rendimiento: los kilos de pergamino seco que se necesitan para sacar un saco de 70 kg de café excelso. La Federación publica su precio de referencia para factor 94, con el que una carga rinde unos 93 kg de excelso; entre más bajo el factor, mejor el café y mejor el pago. La Resolución 5 de 2002 del Comité Nacional de Cafeteros fija los mínimos de calidad del café verde colombiano para exportar. Define el Excelso como grano grande, principalmente plano y parejo, retenido por encima de la malla 14, con una pequeña tolerancia de granos menores retenidos en la malla 12, ampliada al 5 % en 2016. La humedad no puede pasar del 12 %, y sobre muestras de 500 g se revisan defectos, infestación, olor, color y prueba de taza.",
                related = new[] { "ben_trilla", "ben_defectos" } },
            new WikiEntry { id = "pre_cold_brew", category = "Preparación", title = "Cold brew: paciencia en frío", year = "", place = "",
                body = "El cold brew se prepara dejando café de molienda gruesa en agua fría o al clima entre 12 y 24 horas, y después se filtra. Como el agua fría extrae más despacio y disuelve menos algunos compuestos, la bebida se siente más suave y menos ácida. Lo normal es hacer un concentrado y luego diluirlo con agua, leche o hielo.",
                related = new[] { "pre_metodos_filtrado", "pre_extraccion_tds" } },
            new WikiEntry { id = "pre_familia_aeropress", category = "Preparación", title = "La familia AeroPress", year = "2019-2023", place = "",
                body = "Después de la original llegaron otras versiones: la AeroPress Go (2019), compacta para viajar, que guarda los accesorios dentro de su propio pocillo, y la AeroPress XL (2023), con el doble de capacidad para compartir. En 2021 la canadiense Tiny Capital se quedó con la participación mayoritaria de la empresa, y Adler conservó una parte minoritaria.",
                related = new[] { "pre_aeropress_metodos", "hist_aeropress_2005" } },
        };
    }
}
